mapper.select:
SELECT
	(SELECT COUNT(DISTINCT conversation_id) FROM agent_trace


				AND created_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY)


	) AS totalConversations,
	(SELECT COUNT(*) FROM agent_trace


				AND created_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY)


	) AS totalTraces,
	(SELECT COUNT(*) FROM agent_trace WHERE step_type = 'tool_call'

			AND created_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY)

	) AS totalToolCalls,
	(SELECT IFNULL(ROUND(COUNT(*) * 1.0 / COUNT(DISTINCT message_id), 1), 0)
	 FROM agent_trace


				AND created_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY)


	) AS avgStepsPerMessage,
	(SELECT COUNT(*) FROM agent_trace WHERE is_truncated = 1

			AND created_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY)

	) AS totalTruncated,
	(SELECT COUNT(*) FROM eval_candidate WHERE source = 'chat'

			AND created_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY)

	) AS totalDislikes,
	(SELECT COUNT(DISTINCT message_id) FROM agent_trace


				AND created_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY)


	) AS totalMessages
